            int statusCode = response.getStatusLine().getStatusCode();
            if (statusCode != HttpStatus.SC_OK) {
                return null;
            }

            HttpEntity entity = response.getEntity();
            if (entity == null) {
                return null;
            }

            // Check content length to prevent memory exhaustion
            long contentLength = entity.getContentLength();
            if (contentLength > MAX_RESPONSE_SIZE) {
                return null;
            }

            String content = EntityUtils.toString(entity, "UTF-8");

            // Truncate if content exceeds maximum size
            if (content.length() > MAX_RESPONSE_SIZE) {
                content = content.substring(0, MAX_RESPONSE_SIZE);
            }

            return content;

        } catch (URISyntaxException e) {
            return null;
        } catch (IOException e) {
            return null;
        } catch (Exception e) {
            return null;
        } finally {
            try {
                if (response != null) {
                    response.close();
                }
                if (httpClient != null) {
                    httpClient.close();
                }
            } catch (IOException e) {
                // Log error but don't throw
            }
        }
    }

    /**
     * Sanitizes and validates the user-provided URL
     */
    private String sanitizeUrl(String url) {
        if (url == null || url.trim().isEmpty()) {
            return null;
        }

        // Trim whitespace
        url = url.trim();

        // Add protocol if missing
        if (!url.startsWith("http://") && !url.startsWith("https://")) {
            url = "https://" + url;
        }

        try {
            URI uri = new URI(url);
            String scheme = uri.getScheme();

            // Validate protocol
            if (scheme == null || !ALLOWED_PROTOCOLS.contains(scheme.toLowerCase())) {
                return null;
            }

            // Validate URL format
            if (!URL_PATTERN.matcher(url).matches()) {
                return null;
            }

            return url;
        } catch (URISyntaxException e) {
            return null;
        }
    }

    /**
     * Validates that the host is an external, non-private IP address
     */
    private boolean isValidExternalHost(String host) {
        try {
            InetAddress address = InetAddress.getByName(host);
            String hostAddress = address.getHostAddress();

            // Check if it's a private/reserved IP
            for (String blockedRange : BLOCKED_IP_RANGES) {
                if (hostAddress.startsWith(blockedRange)) {
                    return false;
                }
            }

            // Additional check for loopback addresses
            if (address.isLoopbackAddress() || 
                address.isSiteLocalAddress() || 
                address.isLinkLocalAddress()) {
                return false;
            }

            return true;
        } catch (UnknownHostException e) {
            return false;
        }
    }
